import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"ADR-003 HCP Terraform for state","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-hcp-terraform-state.md","filePath":"adr/003-hcp-terraform-state.md","lastUpdated":1786319962000}`),a={name:`adr/003-hcp-terraform-state.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /adr/003-hcp-terraform-state.md for this page in Markdown format</div><h1 id="adr-003-hcp-terraform-for-state" tabindex="-1">ADR-003 HCP Terraform for state <a class="header-anchor" href="#adr-003-hcp-terraform-for-state" aria-label="Permalink to “ADR-003 HCP Terraform for state”">​</a></h1><p><strong>Status:</strong> Accepted</p><p><strong>Date:</strong> 2026-08-09 <strong>Tags:</strong> infrastructure, terraform, state</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>Terraform state for this project holds a database password: Hyperdrive stores the origin credentials as discrete fields, so they are written to state. It needs encryption at rest, locking, and a recoverable history.</li><li>Object-storage backends have a bootstrap problem – you must provision, by hand, the bucket that holds the state that provisions everything else – and the obvious choice here, R2, has no object versioning, so a corrupted state has no rollback.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Use an empty <code>cloud {}</code> block against HCP Terraform. Supply the organization and existing workspace as <code>TF_CLOUD_ORGANIZATION</code> and <code>TF_WORKSPACE</code>, so a fork does not inherit someone else&#39;s deployment targets.</li><li>Keep the default remote execution mode. Cloudflare and database credentials become workspace variables, so they are never held on a developer&#39;s machine, and CI needs exactly one secret (<code>TF_API_TOKEN</code>).</li><li>Ship one backend, not a choice of several. At two environments and four resources, options cost more than they give.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>S3-compatible backend on Cloudflare R2</strong> – keeps everything on one vendor, and <code>use_lockfile = true</code> works because R2 supports conditional writes. Rejected for the manual bucket bootstrap, ten lines of <code>skip_*</code> flags per environment, and no versioning for recovery.</li><li><strong>Local state</strong> – untenable: both environments are shared, and the state carries a password.</li><li><strong>Local execution mode with HCP for state only</strong> – still supported, and documented for anyone who wants it, but it puts production credentials back on developer machines for no gain here.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: no state-storage bootstrap – the workspaces are created once in the UI, but there is no chicken-and-egg bucket to provision first; state encrypted and versioned; locking built in; GitHub stores no infrastructure credentials.</li><li>Negative/Risks: adds a HashiCorp account to an otherwise Cloudflare-only stack, and workspace variables are configured in a web UI rather than the repository. Remote execution means <code>TF_VAR_*</code> in a local shell is ignored, which surprises people expecting a plain backend swap.</li><li>Remote execution also requires each workspace to set <strong>Terraform Working Directory</strong> to <code>envs/&lt;env&gt;</code>, or the uploaded configuration omits the shared <code>modules/</code> directory the roots reference. No <code>cloud</code> block argument sets it, so two workspace settings – working directory and variables – live outside version control. Local execution mode avoids both, at the cost of putting production credentials back on developer machines.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code/Docs: <code>infra/README.md</code>, <code>infra/envs/*/main.tf</code>, <a href="/specs/infra-terraform">Infrastructure spec</a></li><li>Related ADRs: <a href="/adr/002-terraform-wrangler-boundary">ADR-002</a></li></ul>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};